{"implementation":"def solve(case):
    nodes = case["nodes"]
    core = case["core_distance"]
    dists = case["distances"]
    n = len(nodes)
    edges = []
    for a, b, d in dists:
        u, v = (a, b) if a < b else (b, a)
        mr = max(core[a], core[b], d)
        edges.append((mr, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {node: node for node in nodes}
    size = {node: 1 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if size[rx] < size[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        size[rx] += size[ry]
        return True
    mst_edges = []
    total_weight = 0.0
    for mr, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        return {"error": "disconnected", "edges": mst_edges, "total_weight": total_weight}
    return {"edges": mst_edges, "total_weight": total_weight}"}
